	-- {zone:1457} Darnassus · {quest:1123} Rabine Saturna · {quest:1124} Wasteland · {area:2361} Nighthaven
	["The letter from {zone:1457} is already with {quest:1123}: take {quest:1124} from her, in her house in {area:2361}."] = "La carta de {zone:1457} ya está con {quest:1123}: acepta {quest:1124} de ella, en su casa de {area:2361}.",

	-- Step 52: Fly to Everlook
	-- {area:2255} Everlook
	["Fly to {area:2255}"] = "Vuela a {area:2255}",
	-- {area:493} Moonglade · {area:2255} Everlook · {npc:249235} Kaylaena Springwhisper
	["South to {area:493}'s flight master (the Alliance's at the southern end of the valley, the Horde's at its south-western end) and fly to {area:2255} for {npc:249235}'s parts order."] = "Al sur, hasta el maestro de vuelo de {area:493} (el de la Alianza en el extremo sur del valle, el de la Horda en su extremo suroeste), y vuela a {area:2255} por el pedido de piezas de {npc:249235}.",

	-- Step 53: Nami
	-- {npc:228216} Nami · {area:2255} Everlook · {area:16853} Tainted Foothills · {npc:249235} Kaylaena Springwhisper
	["{npc:228216} stands between {area:2255}'s two flight masters. Her crate holds fragile cells that fizzle out in time and when knocked about: fly straight back to the {area:16853} and take it to {npc:249235} without detours or fights (about four minutes in the recording). If it fizzles out anyway, {npc:228216} fills it again."] = "{npc:228216} está entre los dos maestros de vuelo de {area:2255}. Su caja lleva celdas frágiles que se apagan con el tiempo y con los golpes: vuela directo de vuelta a las {area:16853} y llévasela a {npc:249235} sin desvíos ni peleas (unos cuatro minutos en la grabación). Si se apaga de todos modos, {npc:228216} la vuelve a llenar.",

	-- Step 54: Fly to the Tainted Foothills
	-- {area:16853} Tainted Foothills
	["Fly to the {area:16853}"] = "Vuela a las {area:16853}",

	-- Step 55: Kaylaena Springwhisper's workshop
	-- {npc:260626} Bluebell
	["North from {npc:260626} to the workshop, crate first. Watch for Ghansurok, the elite chimaera (level 61) that prowls around the workshop."] = "Al norte desde {npc:260626} hasta el taller, primero la caja. Ojo con Ghansurok, la quimera élite (nivel 61) que ronda el taller.",
	["deliver the crate before it fizzles"] = "entrega la caja antes de que se apague",
	-- {quest:92011} Rubble Rummage · {area:16866} Dae'gun
	["{quest:92011}: in {area:16866}, later in this guide; keep it"] = "{quest:92011}: en {area:16866}, más adelante en esta guía; consérvala",

	-- Step 56: Ketharas
	["South-east to the Hermit's Abode."] = "Al sureste, hasta la Hermit's Abode.",
	-- {quest:96930} The Capricious Corvid · {npc:257753} Curious Crow
	["{quest:96930}: for the {npc:257753}, later in this guide"] = "{quest:96930}: para el {npc:257753}, más adelante en esta guía",
	-- {quest:92171} Taking to New Heights · {npc:254131} Skylord Omnuron
	["{quest:92171}: for {npc:254131}, later in this guide"] = "{quest:92171}: para {npc:254131}, más adelante en esta guía",

	-- Step 57: The Curious Crow
	-- {npc:257753} Curious Crow · {area:17050} Felblood Scar
	["West across the foothills, past the ancients' outpost, to the {npc:257753} at the southern end of {area:17050}."] = "Al oeste, cruzando las colinas y pasando el puesto de los ancianos, hasta el {npc:257753} en el extremo sur de {area:17050}.",
	-- {quest:96931} Heading Up the Mountain · {area:17145} Cradle of Tranquility
	["{quest:96931}: for the {area:17145}, later in this guide"] = "{quest:96931}: para la {area:17145}, más adelante en esta guía",

	-- Step 58: Malorne's Retreat
	-- {area:17144} Malorne's Retreat · {npc:249549} Fenwick Togglespring
	["West along the southern slopes to {area:17144}: {npc:249549}, a gnome test pilot, hangs tangled up in a tree. A sturdy branch lies just south of him."] = "Al oeste por las laderas del sur hasta {area:17144}: {npc:249549}, un piloto de pruebas gnomo, cuelga enredado en un árbol. Una rama firme está justo al sur de él.",
	-- {npc:254501} Tree Branch
	["{npc:254501}, above Fenwick's head"] = "{npc:254501}, sobre la cabeza de Fenwick",

	-- Step 59: Fenwick's survival pack
	["Fenwick's survival pack"] = "La mochila de supervivencia de Fenwick",
	["His pack fell just north of the tree. Open it, then wait half a minute while its safety lock discharges before you open it again."] = "Su mochila cayó justo al norte del árbol. Ábrela y espera medio minuto a que se descargue su cierre de seguridad antes de volver a abrirla.",

	-- Step 60: Brerufa
	-- {npc:256978} Brerufa
	["North-west to Barkskin Burrow, the furbolgs' den in the hillside: {npc:256978} waits just north of its mouth. The Barkskin furbolgs show as hostile until your standing with them improves, but none of them attacked in the recording: the Deadwood furbolgs in the camps around are the ones to fight. {npc:256978} offers more only once this first quest is handed in."] = "Al noroeste, hasta Barkskin Burrow, la guarida de los fúrbolgs en la ladera: {npc:256978} espera justo al norte de su entrada. Los fúrbolgs Piel de Corteza aparecen como hostiles hasta que mejora tu reputación con ellos, pero ninguno atacó en la grabación: hay que pelear con los fúrbolgs Muertobosque de los campamentos de alrededor. {npc:256978} ofrece más solo cuando entregas esta primera misión.",

	-- Step 61: Deadwood Den Guardians
	-- plural, as words: Deadwood Den Guardians = {npc:252063} Deadwood Den Guardian
	["Deadwood Den Guardians"] = "Guardianes del cubil Muertobosque",
	-- {npc:256978} Brerufa
	["The Deadwood furbolgs camp on the slopes north and east of {npc:256978}: kill their Den Guardians."] = "Los fúrbolgs Muertobosque acampan en las laderas al norte y al este de {npc:256978}: mata a sus guardianes del cubil.",

	-- Step 63: Osi Mistpaw
	-- {npc:256646} Osi Mistpaw
	["Inside the burrow: {npc:256646} at the far end."] = "Dentro de la guarida: {npc:256646}, en el fondo.",

	-- Step 64: Bear berries
	["Bear berries"] = "Bayas de oso",
	-- {npc:256978} Brerufa
	["The bear berries grow on the slopes around the burrow: a few on the hill north of {npc:256978}, most of them east of the burrow.\nCareful: Grimroot, an elite treant (level 60), walks the slopes west of the burrow, around 16-20,58-66: give him room."] = "Las bayas de oso crecen en las laderas alrededor de la guarida: unas pocas en la colina al norte de {npc:256978}, la mayoría al este de la guarida.\nCuidado: Grimroot, un ent élite (nivel 60), recorre las laderas al oeste de la guarida, cerca de 16-20,58-66: dale espacio.",

	-- Step 65: Barkskin Burrow
	["Barkskin Burrow"] = "Barkskin Burrow",
	-- {npc:260661} Suma Mossmane · {npc:256660} Thobon Sapclaw · {area:16848} Elderwild · {area:16867} Shrine of Aviana
	["Back to Osi, then the two elders at the back of the burrow. {npc:260661} stands beside Osi, {npc:256660} a little north-west of them, where the recording met him. {npc:260661}'s moss grows around {area:16848}, later in this guide; {npc:256660}'s amulets come from the harpies at the {area:16867}, also later in this guide, and you bring both back here then."] = "De vuelta con Osi, y luego los dos ancianos del fondo de la guarida. {npc:260661} está junto a Osi y {npc:256660}, un poco al noroeste de ellos, donde lo encontró la grabación. El musgo de {npc:260661} crece alrededor de {area:16848}, más adelante en esta guía; los amuletos de {npc:256660} los sueltan las arpías del {area:16867}, también más adelante, y entonces traes las dos cosas aquí.",
	-- {quest:93826} Deal Dread to Deadwood
	["{quest:93826}: on your way back here later; keep it"] = "{quest:93826}: de camino cuando vuelvas aquí más tarde; consérvala",

	-- Step 66: The Western Post
	-- {area:16848} Elderwild · {npc:244517} Sefira Everbright · {npc:249968} Hnaz Blunderflame · {npc:244511} Zet'gan · {npc:244512} Ortak Lomgok
	["North up the valley to {area:16848}, where the Alliance outpost ({npc:244517}, {npc:249968}) and the Horde's ({npc:244511}, {npc:244512}) stand next to each other."] = "Al norte, subiendo por el valle hasta {area:16848}, donde el puesto de la Alianza ({npc:244517}, {npc:249968}) y el de la Horda ({npc:244511}, {npc:244512}) están uno al lado del otro.",

	-- Step 67: The Western Post
	-- {area:16848} Elderwild · {npc:244511} Zet'gan · {npc:244512} Ortak Lomgok · {npc:265788} Kal'tinzan
	["North up the valley to {area:16848}, where the Horde outpost ({npc:244511}, {npc:244512}, {npc:265788}) and the Alliance's stand next to each other."] = "Al norte, subiendo por el valle hasta {area:16848}, donde el puesto de la Horda ({npc:244511}, {npc:244512}, {npc:265788}) y el de la Alianza están uno al lado del otro.",

	-- Step 69: Elderwild
	-- {area:16848} Elderwild
	["The two outposts of {area:16848}."] = "Los dos puestos de {area:16848}.",
	-- {npc:244512} Ortak Lomgok · {quest:96616} Herbs for the Bruised and Weary · {area:16868} Mourning's Rest
	["{npc:244512}: {quest:96616}, on the way back from {area:16868}"] = "{npc:244512}: {quest:96616}, a la vuelta de {area:16868}",

	-- Step 70: Final Death
	-- {quest:92591} Final Death · {npc:260148} Scourge Reanimator · {area:16868} Mourning's Rest
	["{quest:92591}'s {npc:260148} is level 59-60: this guide burns its bone pile once you are 58, on one of its two passes through {area:16868}."] = "El {npc:260148} de {quest:92591} es de nivel 59-60: esta guía quema su pila de huesos cuando tienes 58, en una de sus dos pasadas por {area:16868}.",

	-- Step 71: Final Death
	-- {quest:92592} Final Death · {npc:260148} Scourge Reanimator · {area:16868} Mourning's Rest
	["{quest:92592}'s {npc:260148} is level 59-60: this guide burns its bone pile once you are 58, on one of its two passes through {area:16868}."] = "El {npc:260148} de {quest:92592} es de nivel 59-60: esta guía quema su pila de huesos cuando tienes 58, en una de sus dos pasadas por {area:16868}.",

	-- Step 72: Final Death
	-- {npc:260148} Scourge Reanimator · {quest:92591} Final Death
	["A group choice at your level: the {npc:260148} that answers {quest:92591}'s bone pile is level 59-60."] = "Para ir en grupo a tu nivel: el {npc:260148} que responde a la pila de huesos de {quest:92591} es de nivel 59-60.",

	-- Step 73: Final Death
	-- {npc:260148} Scourge Reanimator · {quest:92592} Final Death
	["A group choice at your level: the {npc:260148} that answers {quest:92592}'s bone pile is level 59-60."] = "Para ir en grupo a tu nivel: el {npc:260148} que responde a la pila de huesos de {quest:92592} es de nivel 59-60.",

	-- Step 74: Moonveil Moss
	-- {npc:260661} Suma Mossmane · {area:16848} Elderwild
	["The moss for {npc:260661} grows around {area:16848}: by the outposts and on the slopes north of them."] = "El musgo para {npc:260661} crece alrededor de {area:16848}: junto a los puestos y en las laderas al norte de ellos.",

	-- Step 75: Eluneth
	-- {npc:264089} Eluneth · {area:16868} Mourning's Rest
	["South-east to {npc:264089} on the slope above {area:16868}."] = "Al sureste, hasta {npc:264089}, en la ladera sobre {area:16868}.",

	-- Step 76: Owl feathers
	["Owl feathers"] = "Plumas de búho",
	-- {npc:264089} Eluneth · {area:16848} Elderwild
	-- plural, as words: Hyjal Owls = {npc:249053} Hyjal Owl · Death Wailers = {npc:249226} Death Wailer
	["The Hyjal Owls roost on the slopes between {npc:264089} and Barkskin Burrow: their feathers are for {area:16848}.\nCareful: Death Wailers (61, rare elites) drift over the western slopes: give them a wide berth.\nCareful: Grimroot, an elite treant (level 60), walks the slopes beside {npc:264089}. He leaves you alone unless you hit him: don't, and pull the owls away from his path."] = "Los búhos de Hyjal anidan en las laderas entre {npc:264089} y Barkskin Burrow: sus plumas son para {area:16848}.\nCuidado: los sollozadores de la muerte (61, élites raros) flotan sobre las laderas del oeste: mantente bien lejos.\nCuidado: Grimroot, un ent élite (nivel 60), recorre las laderas junto a {npc:264089}. No te ataca a menos que lo golpees: no lo hagas, y aleja a los búhos de su camino.",

	-- Step 77: Unmarked Grave
	-- {area:16868} Mourning's Rest
	-- plural, as words: Fleshflay Raveners = {npc:249228} Fleshflay Ravener
	["At the northern end of {area:16868}: something has dug up the grave. The Fleshflay Raveners around it carry what was taken."] = "En el extremo norte de {area:16868}: algo desenterró la tumba. Los Fleshflay Raveners de alrededor llevan lo que se llevaron.",

	-- Step 78: Mourning's Rest
	-- {area:16868} Mourning's Rest · {area:16848} Elderwild
	-- plural, as words: Fleshflay Raveners = {npc:249228} Fleshflay Ravener · Forgotten Soldiers = {npc:249247} Forgotten Soldier · Death Wailers = {npc:249226} Death Wailer
	["The Scourge hold the ruins of {area:16868}, east of {area:16848}: Fleshflay Raveners and Forgotten Soldiers everywhere, Eternal Sentries among them.\nCareful: Death Wailers (61, rare elites) drift over {area:16868}: keep out of their way.\nCareful: Grimroot, the elite treant (level 60), walks the slopes on the way in. He leaves you alone unless you hit him: give him room."] = "La Plaga ocupa las ruinas de {area:16868}, al este de {area:16848}: Fleshflay Raveners y Forgotten Soldiers por todas partes, con Eternal Sentries entre ellos.\nCuidado: los sollozadores de la muerte (61, élites raros) flotan sobre {area:16868}: no te cruces en su camino.\nCuidado: Grimroot, el ent élite (nivel 60), recorre las laderas de la entrada. No te ataca a menos que lo golpees: dale espacio.",

	-- Step 79: Final Death
	-- {area:16868} Mourning's Rest · {item:274411} Survivor's Torch · {npc:260148} Scourge Reanimator
	["Burn the bone pile at the south-eastern end of {area:16868} with the {item:274411}: the {npc:260148} that answers carries the amulet.\nCareful: the {npc:260148} is level 59-60: burn the bone pile last, at full health, with the ruins around it cleared."] = "Quema la pila de huesos del extremo sureste de {area:16868} con la {item:274411}: el {npc:260148} que responde lleva el amuleto.\nCuidado: el {npc:260148} es de nivel 59-60: quema la pila al final, con la vida llena y las ruinas de alrededor despejadas.",

	-- Step 80: Final Death
	-- {npc:260148} Scourge Reanimator
	["A group choice below level 58: the {npc:260148} that answers the burnt bone pile is level 59-60. Grouping up is advised; alone, this guide comes back past the pile later."] = "Para ir en grupo por debajo del nivel 58: el {npc:260148} que responde a la pila de huesos quemada es de nivel 59-60. Se recomienda ir en grupo; si vas solo, esta guía vuelve a pasar por la pila más tarde.",

	-- Step 81: Eluneth and the veteran
	-- {npc:264089} Eluneth
	["{npc:264089} and the veteran"] = "{npc:264089} y el veterano",
	-- {npc:264089} Eluneth · {npc:255009} Veteran of the Third War · {area:16868} Mourning's Rest
	["Back to {npc:264089}, then the ghostly {npc:255009} at {area:16868}'s western edge, where the recording met him, on your way west."] = "De vuelta con {npc:264089}, y luego el fantasmal {npc:255009} en el borde oeste de {area:16868}, donde lo encontró la grabación, de camino al oeste.",

	-- Step 82: Hyjal Silphium
	-- {area:16868} Mourning's Rest · {npc:244512} Ortak Lomgok · {area:16848} Elderwild
	-- plural, as words: Death Wailers = {npc:249226} Death Wailer
	["North-east up the slope from the veteran, north of {area:16868}: {npc:244512}'s silphium grows in the meadows there, where the Horde players in our recordings picked it. Then ride west to {area:16848}.\nCareful: Death Wailers (61, rare elites) drift over these slopes: keep out of their way."] = "Al noreste, subiendo la ladera desde el veterano, al norte de {area:16868}: el silfio de Hyjal de {npc:244512} crece en los prados de ahí, donde lo recogieron los jugadores de la Horda de nuestras grabaciones. Luego ve al oeste hasta {area:16848}.\nCuidado: los sollozadores de la muerte (61, élites raros) flotan sobre estas laderas: no te cruces en su camino.",

	-- Step 83: Elderwild
	["West to the Alliance outpost."] = "Al oeste, hasta el puesto de la Alianza.",

	-- Step 85: To the Summit of Eternity
	-- {quest:91688} To the Summit of Eternity · {npc:254915} Thisalee Crow
	["{quest:91688}: for {npc:254915}, later in this guide; keep it"] = "{quest:91688}: para {npc:254915}, más adelante en esta guía; consérvala",

	-- Step 86: Daythor Brellan and Sefira Everbright
	-- {npc:264521} Daythor Brellan · {npc:244517} Sefira Everbright
	["{npc:264521} and {npc:244517}"] = "{npc:264521} y {npc:244517}",
	-- {npc:244517} Sefira Everbright · {npc:264521} Daythor Brellan
	["The worker {npc:244517} means is a peasant just north of her; {npc:264521} stands between them."] = "El trabajador al que se refiere {npc:244517} es un campesino justo al norte de ella; {npc:264521} está entre los dos.",
	-- {quest:94832} Belle's Ring · {npc:2329} Michelle Belle · {area:87} Goldshire
	["{quest:94832}: {npc:2329} at the Lion's Pride Inn in {area:87}; take it only if you'll pass by"] = "{quest:94832}: {npc:2329}, en la Posada Orgullo de León de {area:87}; tómala solo si vas a pasar por ahí",

	-- Step 87: Elderwild
	-- {npc:244511} Zet'gan · {npc:244512} Ortak Lomgok · {npc:265788} Kal'tinzan
	["West to the Horde outpost: {npc:244511}, then {npc:244512} and {npc:265788} beside him."] = "Al oeste, hasta el puesto de la Horda: {npc:244511}, y luego {npc:244512} y {npc:265788} junto a él.",
	-- {npc:265788} Kal'tinzan · {quest:91794} Flags of Our Forebears · {area:16866} Dae'gun
	["{npc:265788}: {quest:91794}: the flag and the heraldry are in {area:16866}, later in this guide; keep it"] = "{npc:265788}: {quest:91794}: la bandera y los blasones están en {area:16866}, más adelante en esta guía; consérvala",

	-- Step 88: Maruke and Enho Runehoof
	-- {npc:265895} Maruke · {npc:265862} Enho Runehoof
	["{npc:265895} and {npc:265862}"] = "{npc:265895} y {npc:265862}",
	-- {npc:244512} Ortak Lomgok · {npc:265895} Maruke · {area:16848} Elderwild · {npc:265862} Enho Runehoof
	["{npc:244512}'s poultice is for two of the outpost's wounded: {npc:265895} lies at the north end of {area:16848}, {npc:265862} just south of {npc:244512}."] = "La cataplasma de {npc:244512} es para dos heridos del puesto: {npc:265895} está en el extremo norte de {area:16848} y {npc:265862}, justo al sur de {npc:244512}.",

	-- Step 89: Head Scratcher
	-- {quest:92446} Head Scratcher · {npc:244511} Zet'gan
	["{quest:92446} is elite (level 60 in our data): grouping up is advised. {npc:244511}'s rabbit carcass lures him out in the woods by the Deadwood camps south-east of here, on part 3's way back to Barkskin Burrow; his claws come back here at the end of this guide."] = "{quest:92446} es élite (nivel 60 en nuestros datos): se recomienda ir en grupo. El cadáver de conejo de {npc:244511} lo atrae en el bosque junto a los campamentos Muertobosque al sureste de aquí, en la vuelta a Barkskin Burrow de la parte 3; sus garras vuelven aquí al final de esta guía.",

	-- Step 90: The overlook
	["The overlook"] = "El mirador",
	["West to the overlook above the valley: the veteran's old scabbard lies there. Hand his quest in at the scabbard and take the next from it, then use the scabbard in your bags to call his spirit and listen to his story."] = "Al oeste, hasta el mirador sobre el valle: ahí está la vieja vaina del veterano. Entrega su misión en la vaina y toma la siguiente de ella; luego usa la vaina desde tus bolsas para invocar su espíritu y escuchar su historia.",

	-- Step 91: Shalla'kal and Galvinquam Leafsyre
	-- {npc:255683} Shalla'kal · {npc:267109} Galvinquam Leafsyre
	["{npc:255683} and {npc:267109}"] = "{npc:255683} y {npc:267109}",
	-- {area:16868} Mourning's Rest · {area:17145} Cradle of Tranquility · {npc:255683} Shalla'kal · {npc:267109} Galvinquam Leafsyre
	["East past {area:16868} into the {area:17145}: {npc:255683}, the great cat, waits by the path, and {npc:267109} rests in the ruins just south of her."] = "Al este, pasando {area:16868}, hasta la {area:17145}: {npc:255683}, la gran felina, espera junto al sendero, y {npc:267109} descansa en las ruinas justo al sur de ella.",

	-- Step 92: Lisbael Highfeather
	-- {npc:268168} Lisbael Highfeather
	["East across the Cradle to {npc:268168}."] = "Al este, cruzando la Cuna, hasta {npc:268168}.",
	-- {quest:96145} Past Wing and Claw · {npc:260825} Phoebe Highfeather
	["{quest:96145}: for {npc:260825}, later in this guide; keep it"] = "{quest:96145}: para {npc:260825}, más adelante en esta guía; consérvala",

	-- Step 93: Jereman
	-- {npc:267158} Jereman
	["North to the old bridge over the Cradle: touch the crow effigy on it and {npc:267158}, the crow wild god, appears."] = "Al norte, hasta el puente viejo sobre la Cuna: toca la efigie de cuervo que hay en él y aparece {npc:267158}, el dios salvaje cuervo.",

	-- Step 94: The falls and the first kitten
	["The falls and the first kitten"] = "La cascada y la primera cría",
	-- {npc:267109} Galvinquam Leafsyre · {npc:255685} Solstice · {npc:255683} Shalla'kal
	["Fill {npc:267109}'s gourd at the falls beside the bridge. {npc:255685}, one of {npc:255683}'s kittens, plays just west of the falls: walk up to her."] = "Llena el calabacino de {npc:267109} en la cascada junto al puente. {npc:255685}, una de las crías de {npc:255683}, juega justo al oeste de la cascada: acércate a ella.",
	["fill the gourd"] = "llena el calabacino",

	-- Step 95: Johun "Punchy" Dillas's camp
	-- {npc:249234} Johun "Punchy" Dillas
	["{npc:249234}'s camp"] = "El campamento de {npc:249234}",
	-- {npc:249234} Johun "Punchy" Dillas
	["North to {npc:249234} and his crates. Drive the skunks out from behind the crates without attacking them."] = "Al norte, hasta {npc:249234} y sus cajas. Saca a las mofetas de detrás de las cajas sin atacarlas.",

	-- Step 96: Brie
	-- {npc:255773} Brie · {npc:249234} Johun "Punchy" Dillas
	["{npc:255773}, the second kitten, plays just west of {npc:249234}'s camp."] = "{npc:255773}, la segunda cría, juega justo al oeste del campamento de {npc:249234}.",

	-- Step 97: Foxes
	["Foxes"] = "Zorros",
	-- {npc:249234} Johun "Punchy" Dillas · {npc:255183} Jezerelle the Swaying · {npc:256830} Bannerwing Survivor
	["The Rustleaf Foxes are thick in the woods around {npc:249234}'s camp.\nCareful: {npc:255183} (61, rare) walks the woods north of the camp, and a {npc:256830} (60, rare) can turn up there too: leave them be."] = "Los zorros tallóxido abundan en el bosque alrededor del campamento de {npc:249234}.\nCuidado: {npc:255183} (61, rara) recorre el bosque al norte del campamento, y un {npc:256830} (60, raro) también puede aparecer ahí: déjalos tranquilos.",

	-- Step 99: Kala'th
	-- {npc:255693} Kala'th
	["West across the Cradle to {npc:255693}, another of the wild gods."] = "Al oeste, cruzando la Cuna, hasta {npc:255693}, otro de los dioses salvajes.",

	-- Step 100: The burnt buildings
	["The burnt buildings"] = "Los edificios quemados",
	-- {npc:255693} Kala'th
	["The burnt buildings stand in the meadows east of {npc:255693}: the nails and brackets lie among the rubble."] = "Los edificios quemados están en los prados al este de {npc:255693}: los clavos y los soportes están entre los escombros.",

	-- Step 101: Predatory stags
	["Predatory stags"] = "Ciervos depredadores",
	-- {npc:255693} Kala'th
	-- plural, as words: Predatory Hyjal Stags = {npc:256809} Predatory Hyjal Stag · Spectral Frostwyrms = {npc:255691} Spectral Frostwyrm
	["The Predatory Hyjal Stags roam the same meadows, east of {npc:255693}.\nCareful: Spectral Frostwyrms (61, elites) circle over the western meadows: keep out from under them."] = "Los Predatory Hyjal Stags recorren los mismos prados, al este de {npc:255693}.\nCuidado: los Spectral Frostwyrms (61, élites) vuelan en círculos sobre los prados del oeste: no te quedes debajo de ellos.",

	-- Step 103: Marrosis
	-- {npc:267113} Marrosis · {area:16868} Mourning's Rest
	["South to {npc:267113}, another wild god, at {area:16868}'s eastern edge."] = "Al sur, hasta {npc:267113}, otro dios salvaje, en el borde este de {area:16868}.",
	-- {quest:92317} Stolen Life · {npc:256222} Ketharas
	["{quest:92317}: for {npc:256222}, later in this guide; keep it"] = "{quest:92317}: para {npc:256222}, más adelante en esta guía; consérvala",

	-- Step 104: Bones and stolen life
	["Bones and stolen life"] = "Huesos y vida robada",
	-- {area:16868} Mourning's Rest
	-- plural, as words: Fleshflay Raveners = {npc:249228} Fleshflay Ravener · Death Wailers = {npc:249226} Death Wailer · Spectral Frostwyrms = {npc:255691} Spectral Frostwyrm
	["The sun-bleached bones lie all over {area:16868}; the Fleshflay Raveners there carry the drop of stolen life.\nCareful: Death Wailers (61, rare elites) drift over {area:16868}: keep out of their way. Spectral Frostwyrms (61, elites) circle over the meadows around it: keep out from under them."] = "Los huesos blanqueados por el sol están por todo {area:16868}; los Fleshflay Raveners de ahí llevan la gota de vida robada.\nCuidado: los sollozadores de la muerte (61, élites raros) flotan sobre {area:16868}: no te cruces en su camino. Los Spectral Frostwyrms (61, élites) vuelan en círculos sobre los prados de alrededor: no te quedes debajo de ellos.",

	-- Step 105: Final Death
	-- {area:16868} Mourning's Rest · {item:274411} Survivor's Torch · {npc:260148} Scourge Reanimator · {area:16848} Elderwild
	["Burn the bone pile at the south-eastern end of {area:16868} with the {item:274411}: the {npc:260148} that answers carries the amulet. The hand-in waits for the ride back to {area:16848} at the end of this guide.\nCareful: the {npc:260148} is level 59-60: burn the bone pile last, at full health, with the ruins around it cleared."] = "Quema la pila de huesos del extremo sureste de {area:16868} con la {item:274411}: el {npc:260148} que responde lleva el amuleto. La entrega espera a la vuelta a {area:16848}, al final de esta guía.\nCuidado: el {npc:260148} es de nivel 59-60: quema la pila al final, con la vida llena y las ruinas de alrededor despejadas.",

	-- Step 106: Final Death
	-- {npc:260148} Scourge Reanimator · {area:16848} Elderwild
	["A group choice below level 58: the {npc:260148} that answers the burnt bone pile is level 59-60. Grouping up is advised. The hand-in waits for the ride back to {area:16848} at the end of this guide."] = "Para ir en grupo por debajo del nivel 58: el {npc:260148} que responde a la pila de huesos quemada es de nivel 59-60. Se recomienda ir en grupo. La entrega espera a la vuelta a {area:16848}, al final de esta guía.",

	-- Step 107: Final Death
	-- {npc:260148} Scourge Reanimator · {npc:244511} Zet'gan · {area:16848} Elderwild
	["A group choice below level 58: the {npc:260148} that answers the burnt bone pile is level 59-60. Grouping up is advised. {npc:244511} takes the amulet on the ride back to {area:16848} at the end of this guide."] = "Para ir en grupo por debajo del nivel 58: el {npc:260148} que responde a la pila de huesos quemada es de nivel 59-60. Se recomienda ir en grupo. {npc:244511} recibe el amuleto en la vuelta a {area:16848}, al final de esta guía.",

	-- Step 109: Whisperfur
	-- {npc:255771} Whisperfur · {area:16868} Mourning's Rest
	["The last kitten, {npc:255771}, plays at the southern end of {area:16868}."] = "La última cría, {npc:255771}, juega en el extremo sur de {area:16868}.",

	-- Step 110: Shalla'kal and Galvinquam Leafsyre
	-- {npc:255683} Shalla'kal · {npc:267109} Galvinquam Leafsyre
	["North to {npc:255683}, then {npc:267109} in the ruins south of her."] = "Al norte, hasta {npc:255683}, y luego {npc:267109}, en las ruinas al sur de ella.",

	-- Step 111: Corrupted Growth
	-- {area:16867} Shrine of Aviana · {npc:260825} Phoebe Highfeather
	["East from the Cradle towards the {area:16867}, where the Wormwing harpies nest: a corrupted growth on the shrine's western slope starts a quest for {npc:260825}."] = "Al este de la Cuna, hacia el {area:16867}, donde anidan las arpías Alagusano: un brote corrupto en la ladera oeste del santuario inicia una misión para {npc:260825}.",
	["remove the corrupted knots on the trees just north-west of the shrine, on your way"] = "quita los nudos corruptos de los árboles justo al noroeste del santuario, de camino",

	-- Step 112: Skylord Omnuron
	-- {npc:254131} Skylord Omnuron · {npc:260825} Phoebe Highfeather · {area:16867} Shrine of Aviana
	["{npc:254131} and {npc:260825} stand together at the {area:16867}."] = "{npc:254131} y {npc:260825} están juntos en el {area:16867}.",
	-- {quest:92500} A Bit of the Sky · {npc:256222} Ketharas
	["{quest:92500}: for {npc:256222}, later in this guide"] = "{quest:92500}: para {npc:256222}, más adelante en esta guía",

	-- Step 114: The Shrine of Aviana
	-- {area:16867} Shrine of Aviana
	["The {area:16867}"] = "El {area:16867}",

	-- Step 115: The harpy grounds
	["The harpy grounds"] = "El territorio de las arpías",
	-- {npc:256660} Thobon Sapclaw · {object:650219} Jewel of the Horizon (no name in this language: may be words) · {npc:260826} Zarrat Wormwing
	["The Wormwing harpies nest on the slopes north-west of the shrine. They drop the pinfeathers and {npc:256660}'s amulets; the bangles lie in their nests, the {object:650219} in a nest on the western slope, and {npc:260826}, who has Omnuron's spear, is among them. The corrupted knots grow on the trees just north-west of the shrine."] = "Las arpías Alagusano anidan en las laderas al noroeste del santuario. Sueltan las plumas nacientes y los amuletos de {npc:256660}; los brazaletes están en sus nidos, la Joya del Horizonte en un nido de la ladera oeste, y {npc:260826}, que tiene la lanza de Omnuron, anda entre ellas. Los nudos corruptos crecen en los árboles justo al noroeste del santuario.",

	-- Step 117: The way into the Deadwood camps
	["The way into the Deadwood camps"] = "",
	-- {area:17144} Malorne's Retreat · {area:16868} Mourning's Rest
	["The Deadwood camps fill {area:17144}, a sunken valley whose northern end runs in under the cliffs: there is no way down into it from {area:16868}. Go round to the valley's mouth in the south-east and follow it west, then north up into the camps, as players do."] = "",
	-- {area:17144} Malorne's Retreat
	["the mouth of the valley up into {area:17144}"] = "",

	-- Step 118: The Deadwood camps
	["The Deadwood camps"] = "Los campamentos Muertobosque",
	-- {quest:92446} Head Scratcher
	["South-west back towards Barkskin Burrow: the Deadwood camps on the slopes east of the burrow hold the Totemics and Fel-Tenders. An elite named {quest:92446} (level 60) may roam the camps' eastern end."] = "Al suroeste, de vuelta hacia Barkskin Burrow: en los campamentos Muertobosque de las laderas al este de la guarida están los totémicos y los Fel-Tenders. Un élite llamado {quest:92446} (nivel 60) puede rondar el extremo este de los campamentos.",

	-- Step 119: Head Scratcher
	-- {quest:92446} Head Scratcher · {npc:244511} Zet'gan
	["{quest:92446} is elite (level 60 in our data): grouping up is advised. Put {npc:244511}'s rabbit carcass down in the woods at the camps' eastern end, where the Horde players in our recordings fought him, and take his claws."] = "{quest:92446} es élite (nivel 60 en nuestros datos): se recomienda ir en grupo. Deja el cadáver de conejo de {npc:244511} en el bosque del extremo este de los campamentos, donde lo enfrentaron los jugadores de la Horda de nuestras grabaciones, y toma sus garras.",

	-- Step 120: Barkskin Burrow
	-- {npc:260661} Suma Mossmane · {npc:256660} Thobon Sapclaw
	["Into the burrow for the elders, {npc:260661} and {npc:256660}."] = "Entra en la guarida por los ancianos, {npc:260661} y {npc:256660}.",

	-- Step 121: Galvinquam Leafsyre
	-- {area:17145} Cradle of Tranquility · {npc:267109} Galvinquam Leafsyre · {npc:255683} Shalla'kal
	["North-east into the {area:17145}: {npc:267109} rests in the ruins south of {npc:255683}, on your way."] = "Al noreste, hasta la {area:17145}: {npc:267109} descansa en las ruinas al sur de {npc:255683}, de camino.",
	-- {quest:96991} Trail Assist · {npc:264795} Marn Euhorn · {area:16849} Summit of Eternity
	["{quest:96991}: for {npc:264795} at the {area:16849}, later in this guide"] = "{quest:96991}: para {npc:264795} en la {area:16849}, más adelante en esta guía",

	-- Step 122: Jereman
	-- {npc:267158} Jereman
	["On to the old bridge over the Cradle: touch the crow effigy on it and {npc:267158} appears again."] = "Sigue hasta el puente viejo sobre la Cuna: toca la efigie de cuervo que hay en él y {npc:267158} aparece de nuevo.",
	-- {quest:96964} A Clever Creature · {npc:259695} Renalard · {area:16866} Dae'gun
	["{quest:96964}: for {npc:259695} in {area:16866}, just ahead"] = "{quest:96964}: para {npc:259695} en {area:16866}, un poco más adelante",

	-- Step 123: Johun "Punchy" Dillas
	-- {npc:249234} Johun "Punchy" Dillas · {area:16866} Dae'gun
	["North-east across the Cradle to {npc:249234}'s camp at the edge of {area:16866}."] = "Al noreste, cruzando la Cuna, hasta el campamento de {npc:249234} en el borde de {area:16866}.",

	-- Step 124: Elaena Moonwhisper, Witherbeard and Yashiro
	-- {npc:263406} Elaena Moonwhisper · {npc:249052} Witherbeard · {npc:267121} Yashiro
	["{npc:263406}, {npc:249052} and {npc:267121}"] = "{npc:263406}, {npc:249052} y {npc:267121}",
	-- {area:16866} Dae'gun · {npc:263406} Elaena Moonwhisper · {npc:249052} Witherbeard · {npc:267121} Yashiro
	["Into {area:16866}, north of the Cradle: the ruins of a Horde base, now held by demons. {npc:263406} and {npc:249052} camp at its western edge; {npc:267121}, a blademaster, waits a little east of them. Doomguards (elites, levels 58-59) walk among the demons: pull carefully."] = "Entra en {area:16866}, al norte de la Cuna: las ruinas de una base de la Horda, ahora en manos de demonios. {npc:263406} y {npc:249052} acampan en su borde oeste; {npc:267121}, un maestro de espadas, espera un poco al este de ellos. Hay guardias apocalípticos (élites, niveles 58-59) entre los demonios: atrae con cuidado.",

	-- Step 125: Maerion Thaelemaches
	-- {npc:267097} Maerion Thaelemaches · {area:16866} Dae'gun · {quest:97009} Maerion's Misery · {npc:267439} Doomguard Xarkul
	-- plural, as words: Defiling Hounds = {npc:249230} Defiling Hound · Legion Hulks = {npc:249238} Legion Hulk
	["North-east to {npc:267097} at the northern ruins of {area:16866}: take {quest:97009} so the Defiling Hounds drop their spikes while you work the other errands here.\nCareful: Legion Hulks (60, rare elites) stomp through {area:16866}'s camps, and {npc:267439}, an elite (level 61), walks this corner: give them room."] = "Al noreste, hasta {npc:267097}, en las ruinas del norte de {area:16866}: acepta {quest:97009} para que los Defiling Hounds suelten sus púas mientras haces los otros encargos de aquí.\nCuidado: los Legion Hulks (60, élites raros) pisotean los campamentos de {area:16866}, y {npc:267439}, un élite (nivel 61), recorre esta esquina: dales espacio.",

	-- Step 126: Renalard
	-- {area:16866} Dae'gun · {npc:259695} Renalard
	["South-east across {area:16866} to {npc:259695}, the wild god, indoors at its south-eastern edge."] = "Al sureste, cruzando {area:16866}, hasta {npc:259695}, el dios salvaje, bajo techo en su borde sureste.",
	-- {quest:92335} Ashes of the Legion Ascent · {npc:256222} Ketharas
	["{quest:92335}: for {npc:256222}, later in this guide"] = "{quest:92335}: para {npc:256222}, más adelante en esta guía",

	-- Step 127: Dae'gun
	-- {area:16866} Dae'gun · {npc:259695} Renalard · {npc:265788} Kal'tinzan · {item:253249} Horde Flag · {object:656786} Troll Remains (no name in this language: may be words) · {quest:96998} Tribal Colors · {npc:255183} Jezerelle the Swaying · {npc:267439} Doomguard Xarkul
	-- plural, as words: Felguard Sentinels = {npc:249229} Felguard Sentinel · Defiling Hounds = {npc:249230} Defiling Hound · Legion Hulks = {npc:249238} Legion Hulk
	["Work west back through {area:16866}: the Felguard Sentinels and Defiling Hounds are everywhere, the hounds carry the essence, and the Horde base's rubble (wire, scrap and dung) lies all over it. Light the two bonfires on your way, scout the Horde tower in the middle, take Azgalor's ashes west of the tower, and pick up the abandoned supplies, a few just north-west of {npc:259695} and the rest in the western half: {npc:259695}'s tuft of fur, used on a demon, distracts it while you take them.\nHorde: the demons here also drop the Scraps of Horde Heraldry for {npc:265788}, the old {item:253249} stands in the camp north of the south bonfire, and the {object:656786} at the camp's eastern edge start {quest:96998}.\nCareful: Legion Hulks (60, rare elites) stomp through {area:16866}'s camps: give them room. {npc:255183} (61, rare) walks the camp north of the south bonfire: keep away from her.\nCareful: Doomguards (elites, 58-59) stand among the demons, and {npc:267439} (elite, 61) walks the camp: pull the hounds and sentinels to you, away from them."] = "Vuelve al oeste a través de {area:16866}: los Felguard Sentinels y los Defiling Hounds están por todas partes, los sabuesos llevan la esencia, y los escombros de la base de la Horda (alambre, chatarra y estiércol) están por todo el lugar. Enciende las dos hogueras de camino, explora la torre de la Horda del medio, recoge las cenizas de Azgalor al oeste de la torre y toma los suministros abandonados, unos pocos justo al noroeste de {npc:259695} y el resto en la mitad oeste: el mechón de pelaje de {npc:259695}, usado en un demonio, lo distrae mientras los tomas.\nHorda: los demonios de aquí también sueltan los Scraps of Horde Heraldry para {npc:265788}, la vieja {item:253249} está en el campamento al norte de la hoguera del sur, y los restos de trol del borde este del campamento inician {quest:96998}.\nCuidado: los Legion Hulks (60, élites raros) pisotean los campamentos de {area:16866}: dales espacio. {npc:255183} (61, rara) recorre el campamento al norte de la hoguera del sur: mantente lejos de ella.\nCuidado: hay guardias apocalípticos (élites, 58-59) entre los demonios, y {npc:267439} (élite, 61) recorre el campamento: atrae a los sabuesos y centinelas hacia ti, lejos de ellos.",
	["light it"] = "enciéndela",
	["scout the Horde tower"] = "explora la torre de la Horda",
	-- {object:656786} Troll Remains (no name in this language: may be words) · {quest:96998} Tribal Colors · {npc:244511} Zet'gan · {area:16848} Elderwild
	["{object:656786}: {quest:96998}, for {npc:244511} in {area:16848}; keep it"] = "Restos de trol: {quest:96998}, para {npc:244511} en {area:16848}; consérvala",

	-- Step 129: Drawing Down the Malevolent
	-- {npc:263394} Bethra'zel the Feeble · {npc:252457} Mazzogore · {npc:263406} Elaena Moonwhisper
	["{npc:263394} and {npc:252457} are level 60 elites until {npc:263406}'s eye drains them: drain each one first, then fight it. Drained, they are no longer elite and you can take them alone; players in our recordings killed both once drained."] = "{npc:263394} y {npc:252457} son élites de nivel 60 hasta que el ojo de {npc:263406} los drena: drena a cada uno primero y luego lucha. Drenados ya no son élites y puedes con ellos solo; los jugadores de nuestras grabaciones mataron a ambos una vez drenados.",

	-- Step 131: Bethra'zel the Feeble
	-- {npc:263394} Bethra'zel the Feeble · {npc:263406} Elaena Moonwhisper · {npc:252457} Mazzogore · {npc:267439} Doomguard Xarkul · {area:16866} Dae'gun
	-- plural, as words: Legion Hulks = {npc:249238} Legion Hulk
	["North-east to {npc:263394}. Drain him first: use {npc:263406}'s eye on him, and only then fight him. Undrained, he and {npc:252457} are level 60 elites. {npc:267439}, an elite (level 61), walks this corner of {area:16866}: keep out of his way.\nCareful: Legion Hulks (60, rare elites) stomp through {area:16866}'s camps: give them room."] = "Al noreste, hasta {npc:263394}. Drénalo primero: usa el ojo de {npc:263406} sobre él, y solo entonces pelea. Sin drenar, él y {npc:252457} son élites de nivel 60. {npc:267439}, un élite (nivel 61), recorre esta esquina de {area:16866}: no te cruces en su camino.\nCuidado: los Legion Hulks (60, élites raros) pisotean los campamentos de {area:16866}: dales espacio.",

	-- Step 132: Maerion Thaelemaches
	-- {npc:267097} Maerion Thaelemaches · {area:16866} Dae'gun · {npc:263394} Bethra'zel the Feeble · {npc:267439} Doomguard Xarkul
	-- plural, as words: Defiling Hounds = {npc:249230} Defiling Hound · Legion Hulks = {npc:249238} Legion Hulk
	["North-east back to {npc:267097}, in the corner of {area:16866} where {npc:263394} stands: the Defiling Hounds around him drop any spikes you still need.\nCareful: Legion Hulks (60, rare elites) stomp through {area:16866}'s camps, and {npc:267439}, an elite (level 61), walks this corner: give them room."] = "Al noreste, de vuelta con {npc:267097}, en la esquina de {area:16866} donde está {npc:263394}: los Defiling Hounds de alrededor sueltan las púas que todavía te falten.\nCuidado: los Legion Hulks (60, élites raros) pisotean los campamentos de {area:16866}, y {npc:267439}, un élite (nivel 61), recorre esta esquina: dales espacio.",

	-- Step 133: Mazzogore
	-- {npc:263426} Mazzogore the Weak · {area:16866} Dae'gun · {npc:263394} Bethra'zel the Feeble
	["South-west to {npc:263426}, in the middle of {area:16866}: drain him with the eye first, as {npc:263394}, then kill him. Undrained, he is a level 60 elite.\nCareful: Doomguards (elites, 58-59) stand around him: pull him out to you."] = "Al suroeste, hasta {npc:263426}, en el medio de {area:16866}: drénalo primero con el ojo, como a {npc:263394}, y luego mátalo. Sin drenar, es un élite de nivel 60.\nCuidado: hay guardias apocalípticos (élites, 58-59) a su alrededor: atráelo hacia ti.",

	-- Step 134: Elaena Moonwhisper
	-- {quest:96025} As the Crow Flies · {npc:254915} Thisalee Crow
	["{quest:96025}: for {npc:254915} at the Summit"] = "{quest:96025}: para {npc:254915} en la Cumbre",

	-- Step 135: Renalard
	-- {npc:259695} Renalard
	["South-east to {npc:259695}."] = "Al sureste, hasta {npc:259695}.",

	-- Step 136: The Summit of Eternity
	-- {area:16849} Summit of Eternity
	["The {area:16849}"] = "La {area:16849}",
	-- {area:16849} Summit of Eternity · {npc:41861} Fayran Elthas · {npc:264795} Marn Euhorn · {npc:243855} Toron Rockhoof · {npc:254915} Thisalee Crow · {npc:40833} Tiala Whitemane · {npc:243815} Sebelia
	["East up to the {area:16849}, the druids' camp. {npc:41861}, the flight master, stands at its north end; {npc:264795}, {npc:243855} and {npc:254915} along the path south; {npc:40833} indoors next to Thisalee; {npc:243815}, the innkeeper, at the south-east end."] = "Al este, subiendo hasta la {area:16849}, el campamento de los druidas. {npc:41861}, el maestro de vuelo, está en su extremo norte; {npc:264795}, {npc:243855} y {npc:254915}, a lo largo del sendero hacia el sur; {npc:40833}, bajo techo junto a Thisalee; {npc:243815}, la tabernera, en el extremo sureste.",
	-- {npc:41861} Fayran Elthas
	["{npc:41861}, at the flight point"] = "{npc:41861}, en el punto de vuelo",
	-- {npc:243815} Sebelia · {quest:93197} Mending Communications · {npc:11118} Innkeeper Vizzie · {area:2255} Everlook
	["{npc:243815}: {quest:93197}: for {npc:11118} in {area:2255}, at the end"] = "{npc:243815}: {quest:93197}: para {npc:11118} en {area:2255}, al final",

	-- Step 138: As the Crow Flies
