	-- {area:16868} Mourning's Rest · {quest:92592} Final Death
	["Still under 58 after the second pass through {area:16868}? Abandon {quest:92592}: the route doesn't come back for it."] = "¿Sigues por debajo del nivel 58 después de la segunda pasada por {area:16868}? Abandona {quest:92592}: la ruta no vuelve por ella.",

	-- Step 148: Back to Elderwild
	-- {area:16848} Elderwild
	["Back to {area:16848}"] = "De vuelta a {area:16848}",
	-- {area:16848} Elderwild · {npc:265788} Kal'tinzan · {npc:244511} Zet'gan
	["Horde: ride west across the foothills and north up the valley to {area:16848}, about four minutes, for {npc:265788}'s flags, {npc:244511}'s amulet and his war paint wrap, then back up to the Summit."] = "Horda: ve al oeste cruzando las colinas y al norte subiendo por el valle hasta {area:16848}, unos cuatro minutos, por las banderas de {npc:265788}, el amuleto de {npc:244511} y su envoltorio de pintura de guerra; luego vuelve a subir a la Cumbre.",
	-- {npc:244511} Zet'gan · {quest:96999} Wrap Return · {npc:3187} Tai'tasi · {area:367} Sen'jin Village · {zone:1411} Durotar
	["{npc:244511}: {quest:96999}, for {npc:3187} in {area:367}, {zone:1411}; take it only if you'll pass by"] = "{npc:244511}: {quest:96999}, para {npc:3187} en {area:367}, {zone:1411}; tómala solo si vas a pasar por ahí",

	-- Step 149: Back to Elderwild
	-- {npc:244517} Sefira Everbright · {area:16848} Elderwild
	["Alliance: the amulet from the second pass goes to {npc:244517}: ride west across the foothills and north up the valley to {area:16848}, about four minutes, then back up to the Summit."] = "Alianza: el amuleto de la segunda pasada es para {npc:244517}: ve al oeste cruzando las colinas y al norte subiendo por el valle hasta {area:16848}, unos cuatro minutos; luego vuelve a subir a la Cumbre.",

